mapper.select:
select cr_mission_template.resource_id as resource_id, cr_mission_template.title as title, cr_business_template.name as scene_name, cr_business_template.business_type as scene_type, cr_business_template.difficulty as scene_difficulty from cr_mission_template inner join cr_business_template on cr_mission_template.business_template_id = cr_business_template.resource_id
and cr_business_template.business_type = #{type}
and cr_business_template.difficulty = #{difficulty}
and (cr_mission_template.title like #{pattern} or cr_business_template.name like #{pattern})
order by cr_mission_template.update_time desc

select resource_id
from cr_mission_template
where business_template_id = #{businessTemplateId}
